import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        long b = scanner.nextLong();
        long n = scanner.nextLong();
        long minError = 1000000000L;
        long numerator = 0;
        long denominator = 1;
        for (long y = 1; y <= n; y++) {
            long xEstimate = (a * y) / b;
            for (int offset = -5; offset <= 5; offset++) {
                long candidateX = xEstimate + offset;
                long error = Math.abs(b * candidateX - a * y);
                if (error * 1000000000L < minError * b * y) {
                    minError = error;
                    numerator = candidateX;
                    denominator = y;
                }
            }
        }
        System.out.println(numerator + "/" + denominator);
        scanner.close();
    }
}
